mapper.select:
SELECT `user_id` `staffId`, SUM(IF(holiday_type='MATERNITY_LEAVE',`value`,0)) as `maternityLeave` , SUM(IF(holiday_type='COMPENSATORY_LEAVE',`value`,0)) as `compensatoryLeave` , SUM(IF(holiday_type='PATERNITY_LEAVE',`value`,0)) as `paternityLeave`, SUM(IF(holiday_type='BEREAVEMENT_LEAVE',`value`,0)) as `bereavementLeave`, SUM(IF(holiday_type='COMPASSIONATE_LEAVE',`value`,0)) as `compassionateLeave`, SUM(IF(holiday_type='MARRIAGE_LEAVE',`value`,0)) as `marriageLeave`, SUM(IF(holiday_type='SICK_LEAVE',`value`,0)) as `sickLeave`, SUM(IF(holiday_type='ANNUAL_LEAVE',`value`,0)) as `annualLeave`
FROM `holiday_deduct_detail`
WHERE `user_id` in
#{id}
and `create_time` between #{period.begin} and #{period.end}
group by `user_id`
